-- Permission vocabulary and system roles of the communication module
-- Generated by metaphor-schema
--
-- Writes into the identity module's tables (public.permissions, public.roles,
-- public.role_permissions), so those migrations must have run first. Inserts what is
-- missing and never deletes or revokes: what a tenant changed survives a re-run.

DO $$
BEGIN
    IF to_regclass('public.permissions') IS NULL
       OR to_regclass('public.roles') IS NULL
       OR to_regclass('public.role_permissions') IS NULL THEN
        RAISE NOTICE 'seed of the communication permissions skipped: the identity module has not created public.permissions, public.roles and public.role_permissions';
        RETURN;
    END IF;

    UPDATE public.permissions p SET description = v.description
      FROM (VALUES
            ('message:create'::text, 'message'::text, 'create'::text, 'Create message'::text),
            ('message:delete'::text, 'message'::text, 'delete'::text, 'Delete message'::text),
            ('message:purge'::text, 'message'::text, 'purge'::text, 'Purge message'::text),
            ('message:read'::text, 'message'::text, 'read'::text, 'Read message'::text),
            ('message:restore'::text, 'message'::text, 'restore'::text, 'Restore message'::text),
            ('message:update'::text, 'message'::text, 'update'::text, 'Update message'::text),
            ('thread:create'::text, 'thread'::text, 'create'::text, 'Create thread'::text),
            ('thread:delete'::text, 'thread'::text, 'delete'::text, 'Delete thread'::text),
            ('thread:purge'::text, 'thread'::text, 'purge'::text, 'Purge thread'::text),
            ('thread:read'::text, 'thread'::text, 'read'::text, 'Read thread'::text),
            ('thread:restore'::text, 'thread'::text, 'restore'::text, 'Restore thread'::text),
            ('thread:update'::text, 'thread'::text, 'update'::text, 'Update thread'::text)
      ) AS v(name, resource, action, description)
     WHERE p.name = v.name AND (p.metadata->>'deleted_at') IS NULL
       AND p.description IS DISTINCT FROM v.description;

    INSERT INTO public.permissions (name, resource, action, description)
    SELECT v.name, v.resource, v.action, v.description
      FROM (VALUES
            ('message:create'::text, 'message'::text, 'create'::text, 'Create message'::text),
            ('message:delete'::text, 'message'::text, 'delete'::text, 'Delete message'::text),
            ('message:purge'::text, 'message'::text, 'purge'::text, 'Purge message'::text),
            ('message:read'::text, 'message'::text, 'read'::text, 'Read message'::text),
            ('message:restore'::text, 'message'::text, 'restore'::text, 'Restore message'::text),
            ('message:update'::text, 'message'::text, 'update'::text, 'Update message'::text),
            ('thread:create'::text, 'thread'::text, 'create'::text, 'Create thread'::text),
            ('thread:delete'::text, 'thread'::text, 'delete'::text, 'Delete thread'::text),
            ('thread:purge'::text, 'thread'::text, 'purge'::text, 'Purge thread'::text),
            ('thread:read'::text, 'thread'::text, 'read'::text, 'Read thread'::text),
            ('thread:restore'::text, 'thread'::text, 'restore'::text, 'Restore thread'::text),
            ('thread:update'::text, 'thread'::text, 'update'::text, 'Update thread'::text)
      ) AS v(name, resource, action, description)
     WHERE NOT EXISTS (SELECT 1 FROM public.permissions p WHERE p.name = v.name AND (p.metadata->>'deleted_at') IS NULL)
    ON CONFLICT DO NOTHING;

END $$;
